<script setup lang="ts">
import {computed} from 'vue'
import {useStudio} from '../studioContext'
import ReviewBadge from '../ReviewBadge.vue'
import DeliveryPanel from '../DeliveryPanel.vue'
import AppIcon from '../AppIcon.vue'
const s=useStudio()
const pages=computed(()=>[...(s.checklist.value.pages||[])].sort((a:any,b:any)=>rank(a)-rank(b)))
const jobs=(page:string)=>s.p.value.workspace.jobs.filter((j:any)=>j.page===page&&!j.dismissed&&['queued','running','failed','interrupted','partial'].includes(j.state))
function rank(p:any){return p.blocker?0:jobs(p.id).some((j:any)=>['failed','interrupted'].includes(j.state))?1:!p.complete?2:3}
function open(p:any){s.navigate(p.id);s.openChecks&&document.dispatchEvent(new CustomEvent('close-studio-checks'))}
async function adopt(item:any){await s.run(async()=>{await s.saveAll();await s.legacy(await s.api(`/projects/${s.p.value.id}/studio/suggestions/${item.id}/adopt`,'POST',{version:s.p.value.version}));await s.saveAll()})}
async function resolve(c:any){await s.run(async()=>{await s.api(`/projects/${s.p.value.id}/studio/checks/${c.id}`,'POST',{version:s.p.value.version,resolved:true});await s.refresh()})}
</script>
<template><div v-if="s.p.value" class="checks-content"><p class="check-intro">先处理真正缺少的输入；人工核对、AI建议和相关依据更新均不阻止继续制作。</p><article v-for="page in pages" :key="page.id" class="page-check-card"><div class="rail-heading"><h3>{{page.name}}</h3><span>{{page.complete?'内容可用':page.blocker?'需要前置输入':'尚有未完成内容'}} · {{page.done}}/{{page.total}}</span></div><p v-if="page.blocker">{{page.blocker}}</p><button @click="s.goToCheck({page:page.blocker?(page.id==='storyboards'?'clues':page.id==='experience'?'characters':'library'):page.id})">{{page.blocker?'前往前置步骤':'打开此页面'}}</button><div v-for="job in jobs(page.id)" class="check-job"><b>{{job.label}}</b><p>{{job.progress||job.error}}</p><button v-if="['failed','interrupted','partial'].includes(job.state)" :disabled="s.generating.value" @click="s.retryJob(job)">继续未完成项</button></div><details v-if="page.unitIds.length"><summary>具体内容及原因</summary><div v-for="uid in page.unitIds" class="page-check-detail"><ReviewBadge :unit="s.unit(uid)"/><span>{{s.unit(uid)?.name|| (uid.startsWith('character:')?s.rec('character',uid.split(':')[1])?.draft.name:uid.startsWith('storyboard:')?s.rec('storyboard',uid.split(':')[1])?.draft.name:uid.startsWith('visual:')?'画中人物':uid==='documents:main'?'文献资料':uid==='library:main'?'作品资料库':page.name)}}</span><small v-for="reason in s.unit(uid)?.issues">{{reason}}</small></div></details><small v-if="page.reviewCount">{{page.reviewCount}} 组可选人工核对，不影响生成</small></article><details v-if="s.p.value.workspace.generationSuggestions?.length"><summary>新的生成建议（未覆盖人工内容）</summary><section v-for="item in s.p.value.workspace.generationSuggestions"><b>{{item.label}}</b><p>{{item.reason}}</p><details><summary>查看建议内容</summary><pre v-for="change in item.changes">{{JSON.stringify(change.after,null,2)}}</pre></details><button v-if="item.status==='pending'" @click="adopt(item)">使用未冲突的建议</button></section></details><details><summary>AI一致性建议（可选）</summary><p>不计入必须处理事项，不自动标为已核对。</p><button :disabled="s.generating.value" @click="s.generate('check')"><AppIcon name="ai" :size="14"/>生成一致性建议</button><div v-for="c in s.p.value.workspace.consistencyChecks||[]"><p>{{c.message}}</p><button v-if="!c.resolved" @click="resolve(c)">已处理</button></div></details><DeliveryPanel/></div></template>
<style scoped>.page-check-card{border:1px solid #e1e6e2;border-radius:12px;margin:14px 0;padding:18px}.page-check-card h3{margin:0}.page-check-card small,.page-check-card span{font-size:12px;color:#87918d}.page-check-detail{padding:12px 0;display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid #edf0ed}.page-check-detail small{width:100%}.check-job{margin:10px 0;background:#f4f6f3;padding:12px}.checks-content>details{margin:20px 0}.checks-content pre{white-space:pre-wrap;font-size:11px;max-height:220px;overflow:auto}</style>
